import json
try:
    from urllib.parse import quote, urlencode
    info = json.loads('{"path": [], "query": [], "method": "POST", "wrap": "data", "extra": {"call": {"lang": "tr"} } }')
    b = config.get('body')
    if not isinstance(b, dict):
        b = dict()
    for k in list(b.keys()):
        v = b.get(k)
        if v is None or (isinstance(v, str) and (v.strip() == '' or v.strip().startswith('{'))):
            b.pop(k, None)
    url = str(config.get('url') or '')
    for name in info['path']:
        token = '{' + name + '}'
        if token in url:
            val = b.pop(name, None)
            if val is None:
                val = vars.get(name, '')
            url = url.replace(token, quote(str(val).strip(), safe=''))
    q = dict()
    for name in info['query']:
        if name in b:
            q[name] = b.pop(name)
    if info['method'] in ('GET', 'DELETE'):
        q.update(b)
        b = dict()
    if q:
        url = url + ('&' if '?' in url else '?') + urlencode(q)
    config['url'] = url
    if info['method'] in ('GET', 'DELETE'):
        config.pop('body', None)
    else:
        if info.get('wrap'):
            env = dict(info.get('extra') or dict())
            env[info['wrap']] = b
            b = env
        else:
            for k, v in (info.get('extra') or dict()).items():
                b.setdefault(k, v)
        config['body'] = b
except Exception:
    pass

